import React, { useState, useEffect } from 'react';
import { apiCall } from '../../../../api';
import HtmlCell from '../../../../components/HtmlCell';

// frmCustomer — Print Page
// Auto-generated by Form Generator

function PrintPage({ formId, recordId, config, onBack }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const r = await apiCall('_PRINT_ROW', formId, { id: recordId });
        setData(r);
      } catch (e) { console.error(e); }
      finally { setLoading(false); }
    })();
  }, [formId, recordId]);

  if (loading) return <div className="page-content text-center py-5"><div className="spinner-border"></div></div>;

  const row = data?.hdr1?.[0] || data?.hdr?.[0] || {};

  const SKIP = new Set(['btns', 'User_Id', 'LOCK', 'LOCK_User_Id', 'Attachments', '_footer']);
  const fields = Object.entries(row).filter(([k]) => !SKIP.has(k) && row[k] !== '' && row[k] !== null && row[k] !== undefined);

  return (
    <div className="page-content animate-fade">
      <div className="no-print d-flex justify-content-between mb-3">
        <button className="btn btn-outline-secondary btn-sm" onClick={onBack}>
          <i className="bi bi-arrow-left"></i> Back
        </button>
        <button className="btn btn-primary btn-sm" onClick={() => window.print()}>
          <i className="bi bi-printer"></i> Print
        </button>
      </div>
      <div className="card" id="print-area">
        <div className="card-body">
          <h5 className="text-center mb-3" style={{fontWeight:700}}>Customer Master</h5>
          <table className="table table-bordered table-sm" style={{fontSize:13}}>
            <tbody>
              {fields.map(([key, val]) => (
                <tr key={key}>
                  <th style={{width:200,background:'#f8f9fa'}}>{key}</th>
                  <HtmlCell value={val} />
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default PrintPage;
